sels=['v2csreprss','v2cseeorgs','v2cscnsult','v2csprtcpt','v2x_cspart','v2xcs_ccsi','v2x_frassoc_thick','v2caassemb','v2x_freexp_altinf','v2meslfcen','v2clrelig','v2csrlgrep','v3cllabrig','v2cltort','v2clkill','v2edteunion','v2edteunionindp']
